-- police_system / modules/radio_voice/shared/db.lua
-- The fixed dispatcher voice database (data/voice.json, generated by tools/build_db.py from the sounds_source folder).
-- Loaded once per side at the first VOICE.load(); nil when the file is missing or of another format (the voice is
-- then simply silent, nothing else depends on it).

VOICE = VOICE or {}

function VOICE.load()
    if VOICE.db ~= nil then return VOICE.db or nil end
    VOICE.db = false
    local path = POLICE.VOICE.DB
    local f = fileExists(path) and fileOpen(path, true)
    if not f then
        outputDebugString("[police_system] radio_voice: " .. path .. " missing, dispatcher voice off", 2)
        return nil
    end
    local src = fileRead(f, fileGetSize(f))
    fileClose(f)
    local db = fromJSON(src)
    if type(db) ~= "table" or tonumber(db.format) ~= 1 or type(db.phrases) ~= "table" or type(db.triggers) ~= "table" then
        outputDebugString("[police_system] radio_voice: bad " .. path .. ", dispatcher voice off", 2)
        return nil
    end
    VOICE.db = db
    return db
end

-- GTA rotZ (0 = north, 90 = west) -> 1 north, 2 west, 3 south, 4 east (maps.directions order)
function VOICE.dirIndex(heading)
    return math.floor(((tonumber(heading) or 0) + 45) % 360 / 90) + 1
end
